package net.officefloor.hq.app.setting;

/** The body of the settings being saved, as typed: the clerk limit (blank: no limit) and the floor, the terms and the late percent (each null or blank: left as it is), and the policy date (null: left as it is; blank: none, so the sheet's today), and the period numbering from-date (null: left as it is; blank: off), and the cap and the proof threshold (each null: left as it is; blank: none), and the grace days (null: left as it is; blank: off), and the terms of a grade's own, by grade (each left out, null or blank: left as it is), and the from-date (yyyy-mm-dd) each dated setting saved is recorded from, by setting key (left out or blank: the sheet's today), and the roles each action is permitted to, by action, as a comma separated list (left out or null: left as it is; blank: the standing rule). */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String cap, String proofThreshold, String graceDays,
        java.util.Map<String, String> gradeTerms, java.util.Map<String, String> from, java.util.Map<String, String> perms) {
}
package net.officefloor.hq.app.setting;

/**
 * The settings of a sheet being saved, each null when it is left as it is: the clerk limit with two decimals,
 * "" for no limit, the floor with two decimals, the terms as a whole number of days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" for none, and the period numbering from-date as yyyy-MM-dd, "" for off, and the cap and the proof threshold, each with two decimals, "" for none, and the grace days as a whole number of days, "" for off.
 * {@code gradeTerms} are the terms of a grade's own being saved, as a whole number of days, by grade (a grade left out is left as it is).
 * {@code perms} are the roles each action is permitted to being saved, by action in {@link Settings#PERM_ACTIONS} order, as a comma separated list, "" for the standing rule.
 * {@code from} is the from-date given for a dated setting, by setting key (a key left out is saved from the sheet's today, and audited without one).
 */
public record SheetSettings(String sheetId, String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom, String cap, String proofThreshold, String graceDays,
        java.util.SortedMap<String, String> gradeTerms, java.util.Map<String, java.time.LocalDate> from,
        java.util.Map<String, String> perms) {
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class ApplySettings {
    // A dated setting is recorded from its from-date, else from the sheet's today, keeping the values recorded from other dates.
    public void apply(@Val SheetSettings settings, Settings store, Sheets sheets) {
        LocalDate today = sheets.today(settings.sheetId());
        if (settings.clerkLimit() != null) {
            dated(settings, store, today, Settings.CLERK_LIMIT, settings.clerkLimit());
        }
        if (settings.floor() != null) {
            dated(settings, store, today, Settings.FLOOR, settings.floor());
        }
        if (settings.terms() != null) {
            dated(settings, store, today, Settings.TERMS, settings.terms());
        }
        settings.gradeTerms().forEach((grade, days) -> dated(settings, store, today, Settings.gradeTermsKey(grade), days));
        if (settings.latePct() != null) {
            dated(settings, store, today, Settings.LATE_PCT, settings.latePct());
        }
        if (settings.policyDate() != null) {
            store.set(settings.sheetId(), Settings.POLICY_DATE, settings.policyDate());
        }
        if (settings.periodNumberingFrom() != null) {
            store.set(settings.sheetId(), Settings.PERIOD_NUMBERING_FROM, settings.periodNumberingFrom());
        }
        if (settings.cap() != null) {
            dated(settings, store, today, Settings.CAP, settings.cap());
        }
        if (settings.proofThreshold() != null) {
            dated(settings, store, today, Settings.PROOF_THRESHOLD, settings.proofThreshold());
        }
        if (settings.graceDays() != null) {
            store.set(settings.sheetId(), Settings.GRACE_DAYS, settings.graceDays());
        }
        settings.perms().forEach((action, roles) -> store.set(settings.sheetId(), Settings.permKey(action), roles));
    }

    private static void dated(SheetSettings settings, Settings store, LocalDate today, String key, String value) {
        store.set(settings.sheetId(), key, settings.from().getOrDefault(key, today), value);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditSettingChanged {
    // One line per setting saved: the clerk limit, then the floor, then the terms, then each grade's own terms by grade, then the late percent, then the policy date, then the period numbering from-date, then the cap, then the proof threshold, then the grace days, then each action's permitted roles, in the matrix's order. A dated setting saved with a from-date ends with from=<date>.
    public void audit(@Val SheetSettings settings, ServerHttpConnection connection, Audit audit) {
        if (settings.clerkLimit() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.CLERK_LIMIT, "value=" + settings.clerkLimit(), from(settings, Settings.CLERK_LIMIT)));
        }
        if (settings.floor() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.FLOOR, "value=" + settings.floor(), from(settings, Settings.FLOOR)));
        }
        if (settings.terms() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.TERMS, "value=" + settings.terms(), from(settings, Settings.TERMS)));
        }
        settings.gradeTerms().forEach((grade, days) -> audit.record(dated(settings, connection,
                "key=" + Settings.gradeTermsKey(grade), "value=" + days, from(settings, Settings.gradeTermsKey(grade)))));
        if (settings.latePct() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.LATE_PCT, "value=" + settings.latePct(), from(settings, Settings.LATE_PCT)));
        }
        if (settings.policyDate() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.POLICY_DATE, "value=" + settings.policyDate()));
        }
        if (settings.periodNumberingFrom() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.PERIOD_NUMBERING_FROM, "value=" + settings.periodNumberingFrom()));
        }
        if (settings.cap() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.CAP, "value=" + settings.cap(), from(settings, Settings.CAP)));
        }
        if (settings.proofThreshold() != null) {
            audit.record(dated(settings, connection, "key=" + Settings.PROOF_THRESHOLD, "value=" + settings.proofThreshold(),
                    from(settings, Settings.PROOF_THRESHOLD)));
        }
        if (settings.graceDays() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.GRACE_DAYS, "value=" + settings.graceDays()));
        }
        settings.perms().forEach((action, roles) -> audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(),
                Audit.user(connection), "key=" + Settings.permKey(action), "value=" + roles)));
    }

    private static String from(SheetSettings settings, String key) {
        java.time.LocalDate from = settings.from().get(key);
        return from == null ? null : "from=" + from;
    }

    /** A dated setting's line: its key and value, then its from-date when one was given. */
    private static String dated(SheetSettings settings, ServerHttpConnection connection, String key, String value, String from) {
        String line = Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection), key, value);
        return from == null ? line : line + " " + from;
    }
}
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String FLOOR_DEFAULT = "1.00";
    public static final String TERMS = "terms";
    public static final String TERMS_DEFAULT = "14";
    /** The grades a sheet may give terms of their own, each kept under {@link #gradeTermsKey}. */
    public static final List<String> GRADES = List.of("A", "B", "C");
    public static final String LATE_PCT = "late-pct";
    public static final String LATE_PCT_DEFAULT = "0.00";
    public static final String POLICY_DATE = "policy-date";
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";
    /** Days after a period's to-date it stays open once the sheet's today passes it (undated); blank is off. */
    public static final String GRACE_DAYS = "grace-days";
    /** The settings that carry a figure: each value is kept from a from-date (see {@link #on}). */
    public static final List<String> DATED = List.of(CLERK_LIMIT, FLOOR, TERMS, gradeTermsKey("A"), gradeTermsKey("B"),
            gradeTermsKey("C"), LATE_PCT, CAP, PROOF_THRESHOLD);
    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";
    /** A role that sees everything and may change nothing; never one the permission matrix allows an action to. */
    /** The clerk limit in force on the sheet's today; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        String value = current(sheetId, CLERK_LIMIT);
        return value.isEmpty() ? null : new BigDecimal(value);
    }

    /** The cap in force on the sheet's today, with two decimals: what a person's due-total is at most; null when there is none. */
    public BigDecimal cap(String sheetId) {
        String value = current(sheetId, CAP);
        return value.isEmpty() ? null : new BigDecimal(value);
    }

    /** The proof threshold in force on the date: a claim dated then whose due is above it is settled only with a proof; null when there is none. */
    public BigDecimal proofThreshold(String sheetId, LocalDate date) {
        String value = on(sheetId, PROOF_THRESHOLD, date);
        return value.isEmpty() ? null : new BigDecimal(value);
    }

    /** A person's due-total held to the sheet's cap; null (n/a) stays null. */
    public BigDecimal capped(String sheetId, BigDecimal dueTotal) {
        BigDecimal cap = cap(sheetId);
                numberingFrom = LocalDate.parse(numberingFrom).toString();
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The period numbering from-date must be a date (yyyy-mm-dd).");
            }
        }
        String cap = body == null || body.cap() == null ? null : body.cap().trim();
        if (cap != null && !cap.isEmpty()) {
            if (!AMOUNT.matcher(cap).matches()) {
                throw new InvalidSettingException("The cap must be an amount of 0.00 or more, with up to two decimals.");
            }
            cap = twoDecimals(cap);
        }
        String threshold = body == null || body.proofThreshold() == null ? null : body.proofThreshold().trim();
        if (threshold != null && !threshold.isEmpty()) {
            if (!AMOUNT.matcher(threshold).matches()) {
                throw new InvalidSettingException("The proof threshold must be an amount of 0.00 or more, with up to two decimals.");
            }
            threshold = twoDecimals(threshold);
        }
        String grace = body == null || body.graceDays() == null ? null : body.graceDays().trim();
        if (grace != null && !grace.isEmpty()) {
            if (!DAYS.matcher(grace).matches()) {
                throw new InvalidSettingException("The grace days must be a whole number of days, 0 or more.");
            }
            grace = Integer.toString(Integer.parseInt(grace));
        }
        Map<String, LocalDate> from = new java.util.HashMap<>();
        if (body != null && body.from() != null) {
            for (Map.Entry<String, String> entry : body.from().entrySet()) {
                String key = entry.getKey() == null ? "" : entry.getKey().trim();
                String date = entry.getValue() == null ? "" : entry.getValue().trim();
                if (date.isEmpty()) {
                    continue;
                }
                if (!Settings.DATED.contains(key)) {
                    throw new InvalidSettingException("Only a setting that carries a figure has a from-date.");
                }
                try {
                    from.put(key, LocalDate.parse(date));
                } catch (DateTimeParseException e) {
                    throw new InvalidSettingException("The from-date must be a date (yyyy-mm-dd).");
                }
            }
        }
        Map<String, String> perms = new java.util.LinkedHashMap<>();
        if (body != null && body.perms() != null) {
            for (String action : body.perms().keySet()) {
                if (!Settings.PERM_ACTIONS.contains(action)) {
                    throw new InvalidSettingException("Permissions are set only for open, settle, void, reassign, close and reopen.");
                }
            }
            for (String action : Settings.PERM_ACTIONS) {
                String typedRoles = body.perms().get(action);
                if (typedRoles == null) {
                    continue;
                }
                java.util.List<String> roles = new java.util.ArrayList<>();
                if (!typedRoles.isBlank()) {
                    for (String role : typedRoles.split(",")) {
                        String r = role.trim();
                        if (!Settings.ROLES.contains(r)) {
                            throw new InvalidSettingException("The roles allowed to " + action + " must be clerk or steward, separated by commas.");
                        }
                        if (!roles.contains(r)) {
                            roles.add(r);
                        }
                    }
                }
                perms.put(action, String.join(",", roles));
            }
        }
        boolean others = !floor.isEmpty() || !terms.isEmpty() || !gradeTerms.isEmpty() || !latePct.isEmpty() || policyDate != null
                || numberingFrom != null || cap != null || threshold != null || grace != null || !perms.isEmpty();
        if (typed == null && !others) {
            typed = "";
        }
        String limit = typed == null || (typed.isEmpty() && others) ? null
                : typed.isEmpty() ? "" : twoDecimals(typed);
        settingsOut.set(new SheetSettings(sheetId.trim(), limit, floor.isEmpty() ? null : twoDecimals(floor),
                terms.isEmpty() ? null : Integer.toString(Integer.parseInt(terms)),
                latePct.isEmpty() ? null : twoDecimals(latePct), policyDate, numberingFrom, cap, threshold, grace, gradeTerms, from, perms));
    }

    private static String twoDecimals(String amount) {
        return new BigDecimal(amount).setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}

